class SwimFailureDetector:
    def __init__(self, node_id: str, suspect_timeout: int = 3):
        self.node_id = node_id
        self.suspect_timeout = suspect_timeout
        # peer_id -> {"state": str, "incarnation": int, "timer": int}
        self.peers = {}

    def join(self, peer_id: str) -> None:
        if peer_id == self.node_id:
            return
        self.peers[peer_id] = {
            "state": "ALIVE",
            "incarnation": 0,
            "timer": 0
        }

    def probe(self, target_id: str, direct_ok: bool, proxy_acks: list[bool] | None = None) -> str:
        if target_id not in self.peers:
            self.join(target_id)

        peer = self.peers[target_id]
        if peer["state"] == "DEAD":
            return "DEAD"

        # 1. Direct probe succeeds
        if direct_ok:
            peer["state"] = "ALIVE"
            peer["timer"] = 0
            return "ALIVE"

        # 2. Indirect probe via proxies
        if proxy_acks and any(proxy_acks):
            peer["state"] = "ALIVE"
            peer["timer"] = 0
            return "ALIVE"

        # 3. Both direct and indirect probes failed -> transition to SUSPECT
        if peer["state"] != "SUSPECT":
            peer["state"] = "SUSPECT"
            peer["timer"] = self.suspect_timeout

        return "SUSPECT"

    def refute(self, peer_id: str, incarnation: int) -> bool:
        if peer_id not in self.peers:
            return False
        peer = self.peers[peer_id]
        if incarnation > peer["incarnation"]:
            peer["incarnation"] = incarnation
            peer["state"] = "ALIVE"
            peer["timer"] = 0
            return True
        return False

    def tick(self) -> list[str]:
        newly_dead = []
        for peer_id, info in self.peers.items():
            if info["state"] == "SUSPECT":
                info["timer"] -= 1
                if info["timer"] <= 0:
                    info["state"] = "DEAD"
                    newly_dead.append(peer_id)
        return newly_dead

    def get_state(self, peer_id: str) -> str | None:
        peer = self.peers.get(peer_id)
        return peer["state"] if peer else None
